<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $status = isset( $_GET['notification_status'] ) ? sanitize_key( wp_unslash( $_GET['notification_status'] ) ) : 'all'; if ( ! in_array( $status, array( 'all', 'unread', 'read' ), true ) ) { $status = 'all'; } $page = isset( $_GET['paged'] ) ? max( 1, absint( $_GET['paged'] ) ) : 1; $result = sd_notifications_query( $status, $page ); ?><section class="sd-notification-center"><header class="sd-page-heading"><span class="sd-eyebrow"><?php esc_html_e( 'Stay in the loop', 'social-discovery' ); ?></span><h1><?php esc_html_e( 'Notifications', 'social-discovery' ); ?></h1><p><?php esc_html_e( 'Updates about your connections, communities, activity, and messages.', 'social-discovery' ); ?></p></header><?php if ( sd_notifications_available() ) : ?><nav class="sd-notification-filters" aria-label="<?php esc_attr_e( 'Notification filters', 'social-discovery' ); ?>"><?php foreach ( array( 'all' => __( 'All', 'social-discovery' ), 'unread' => __( 'Unread', 'social-discovery' ), 'read' => __( 'Read', 'social-discovery' ) ) as $key => $label ) : ?><a class="<?php echo $status === $key ? 'is-active' : ''; ?>" href="<?php echo esc_url( add_query_arg( 'notification_status', $key, sd_home_url( 'notifications' ) ) ); ?>"><?php echo esc_html( $label ); ?></a><?php endforeach; ?></nav><div class="sd-notification-actions"><button type="button" class="sd-button sd-button-outline" data-sd-mark-all><?php esc_html_e( 'Mark all as read', 'social-discovery' ); ?></button></div><?php if ( empty( $result['notifications'] ) ) : ?><div class="sd-empty-state"><h2><?php esc_html_e( 'No notifications here', 'social-discovery' ); ?></h2><p><?php esc_html_e( 'You are all caught up for this filter.', 'social-discovery' ); ?></p></div><?php else : ?><div class="sd-notification-list"><?php foreach ( $result['notifications'] as $notification ) { get_template_part( 'template-parts/notifications/notification-item', null, array( 'notification' => $notification ) ); } ?></div><?php endif; ?><?php else : ?><div class="sd-empty-state"><h2><?php esc_html_e( 'Notifications are not available yet', 'social-discovery' ); ?></h2><p><?php esc_html_e( 'Enable the BuddyPress Notifications component to use this center.', 'social-discovery' ); ?></p></div><?php endif; ?></section>
